  private rankFor(total: number) { return [...SERVICE_RANKS].reverse().find(rank => total >= rank.threshold) || SERVICE_RANKS[0]; }
  private currentServiceRecord() { return this.serviceRanks.find(record => record.id === this.playerName.toLowerCase()) || { id:this.playerName.toLowerCase(), name:this.playerName, total:0, games:0, wins:0, bestRound:0 }; }
  private renderServiceRanks() { const list = document.getElementById("service-ranks"), guide = document.getElementById("rank-guide"); if (guide) guide.innerHTML = SERVICE_RANKS.map(rank => `<li><b>${rank.mark}</b> ${rank.name}<span>${rank.threshold.toLocaleString("en-US")}</span></li>`).join(""); if (!list) return; const records = [...this.serviceRanks].sort((a,b) => b.total - a.total || b.bestRound - a.bestRound); list.innerHTML = records.length ? records.slice(0,8).map((record, index) => { const rank = this.rankFor(record.total); return `<li><span>#${index + 1} <b class="rank-mark">${rank.mark}</b> ${record.name}</span><b>${rank.name}</b><small>${record.total.toLocaleString("en-US")} service points · ${record.games} rounds</small></li>`; }).join("") : "<li>No service records yet</li>"; }
  private async refreshServiceRanks() { try { const response=await fetch(this.apiEndpoint("/api/ranks")), data=await response.json(); if (!data.configured || !Array.isArray(data.records)) return; const merged=new Map(this.serviceRanks.map(record => [record.id,{...record}])); for (const remote of data.records) { const local=merged.get(remote.id); merged.set(remote.id,local ? { ...remote, total:Math.max(Number(remote.total)||0,local.total), games:Math.max(Number(remote.games)||0,local.games), wins:Math.max(Number(remote.wins)||0,local.wins), bestRound:Math.max(Number(remote.bestRound)||0,local.bestRound) } : remote); } this.serviceRanks=[...merged.values()].sort((a,b)=>b.total-a.total || b.bestRound-a.bestRound).slice(0,80); localStorage.setItem("hb2-service-ranks",JSON.stringify(this.serviceRanks)); this.renderServiceRanks(); } catch { /* Local service progress remains available offline. */ } }
  private async recordServiceRank(points: number, victory: boolean) { const factors: Record<string,number> = {easy:.7,normal:1,hard:1.25,extreme:1.6}; const gained = Math.round(points * (factors[this.difficulty] || 1)); const id = this.playerName.toLowerCase(), local = this.serviceRanks.find(record => record.id === id) || { id, name:this.playerName, total:0, games:0, wins:0,bestRound:0 }, previousRank=this.rankFor(local.total); local.name=this.playerName; local.total+=gained; local.games++; local.wins+=victory?1:0; local.bestRound=Math.max(local.bestRound,gained); if (!this.serviceRanks.includes(local)) this.serviceRanks.push(local); const advancedRank=this.rankFor(local.total); this.latestRankPromotion=advancedRank.name !== previousRank.name ? advancedRank.name : ""; this.latestServiceGained=gained; this.serviceRanks.sort((a,b)=>b.total-a.total); this.serviceRanks.splice(80); localStorage.setItem("hb2-service-ranks", JSON.stringify(this.serviceRanks)); this.renderServiceRanks(); try { const response = await fetch(this.apiEndpoint("/api/ranks"), { method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({name:this.playerName,difficulty:this.difficulty,points,victory,total:local.total,games:local.games,wins:local.wins,bestRound:local.bestRound}) }), data = await response.json(); if (data.configured && Array.isArray(data.records)) { this.serviceRanks=data.records; this.latestServiceGained=Number(data.gained)||gained; localStorage.setItem("hb2-service-ranks",JSON.stringify(this.serviceRanks)); this.renderServiceRanks(); } } catch { return; } }
  private getAnalyticsSessionId() { const key = "hb2-analytics-session"; let id = localStorage.getItem(key); if (!id) { id = typeof crypto.randomUUID === "function" ? crypto.randomUUID() : `session-${Date.now()}-${Math.random().toString(36).slice(2, 14)}`; localStorage.setItem(key, id); } return id; }
  private renderAnalytics(data: {configured?:boolean;totals?:{uniqueSessions?:number;starts?:number;completions?:number};countries?:Array<{country:string;starts:number}>}) { const panel = document.getElementById("community-stats")!, endPanel = document.getElementById("end-community-stats")!; if (!data.configured || !data.totals) { panel.hidden = true; endPanel.hidden = true; return; } panel.hidden = false; endPanel.hidden = false; const sessions = String(data.totals.uniqueSessions || 0), starts = String(data.totals.starts || 0); (document.getElementById("stat-sessions") as HTMLElement).textContent = sessions; (document.getElementById("stat-starts") as HTMLElement).textContent = starts; (document.getElementById("stat-completions") as HTMLElement).textContent = String(data.totals.completions || 0); (document.getElementById("end-stat-sessions") as HTMLElement).textContent = sessions; (document.getElementById("end-stat-starts") as HTMLElement).textContent = starts; const names = typeof Intl.DisplayNames === "function" ? new Intl.DisplayNames(["de"], { type: "region" }) : undefined; (document.getElementById("stat-countries") as HTMLElement).textContent = data.countries?.length ? `Top countries: ${data.countries.map(item => `${names?.of(item.country) || item.country} ${item.starts}`).join(" · ")}` : "Countries appear after the first deployed round."; }
