  private async trackAnalytics(event: "start" | "complete", won = false) { try { const response = await fetch(this.apiEndpoint("/api/analytics"), { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ event, won, difficulty: this.difficulty, sessionId: this.analyticsSessionId }) }); this.renderAnalytics(await response.json()); } catch { /* Statistics never interrupt a round. */ } }
  private recordHallOfFame(victory: boolean, score: number) { const prior = this.hallOfFame.filter(record => record.difficulty === this.difficulty && record.name.toLowerCase() === this.playerName.toLowerCase()).reduce((best, record) => Math.max(best, record.score), 0); this.newHallHighScore = score > prior; const record = { name: this.playerName, score, mass: Math.floor(this.player.mass), wins: victory ? 1 : 0, runs: 1, combo: this.maxCombo, difficulty: this.difficulty }; this.latestHallRecord = record; this.hallOfFame.push(record); this.hallOfFame.sort((a, b) => a.difficulty.localeCompare(b.difficulty) || b.score - a.score || b.mass - a.mass); this.hallOfFame.splice(160); localStorage.setItem("hb2-hall-of-fame-season-1", JSON.stringify(this.hallOfFame)); void this.recordServiceRank(score, victory); return record; }
