  private drawPlayerRankBadge(ctx:CanvasRenderingContext2D) { const radius=this.player.displayRadius*(1+this.pulse), rank=this.rankFor(this.currentServiceRecord().total), level=Math.max(0,SERVICE_RANKS.indexOf(rank)), size=Math.max(16,Math.min(42,radius*.36)), x=this.player.x+radius*.64, y=this.player.y+radius*.5; ctx.save(); ctx.shadowColor=level >= 8 ? "#ffb347" : "#ffd15c"; ctx.shadowBlur=8+level; const gradient=ctx.createLinearGradient(x,y-size*.55,x,y+size*.65); gradient.addColorStop(0,level >= 8 ? "#734213" : "#244c69"); gradient.addColorStop(1,"#071827"); ctx.fillStyle=gradient; ctx.strokeStyle=level >= 8 ? "#ffb347" : "#ffd15c"; ctx.lineWidth=Math.max(1.5,size*.09); ctx.beginPath(); ctx.moveTo(x-size*.55,y-size*.48); ctx.lineTo(x+size*.55,y-size*.48); ctx.lineTo(x+size*.46,y+size*.27); ctx.lineTo(x,y+size*.68); ctx.lineTo(x-size*.46,y+size*.27); ctx.closePath(); ctx.fill(); ctx.stroke(); ctx.shadowBlur=0; ctx.fillStyle="#fff4ba"; ctx.textAlign="center"; ctx.textBaseline="middle"; ctx.font=`900 ${Math.max(10,size*.48)}px system-ui`; ctx.fillText(rank.mark,x,y-size*.02); ctx.restore(); }
  private frame(time: number) { const dt = Math.min(.035, (time - this.lastTime || 16) / 1000); this.lastTime = time; this.syncAmbientMusic(); this.update(dt); if (this.arenaBreakerUntil && performance.now() >= this.arenaBreakerUntil) document.getElementById("arena-breaker")!.hidden = true; if (this.apexRiftUntil && performance.now() >= this.apexRiftUntil) document.getElementById("rift-alert")!.hidden = true; if (this.missionAlertUntil && performance.now() >= this.missionAlertUntil) document.getElementById("mission-alert")!.hidden = true; if (this.toxicKamikazeUntil && performance.now() >= this.toxicKamikazeUntil) { document.getElementById("toxic-alert")!.hidden = true; this.toxicKamikazeIds.clear(); this.toxicKamikazeTargets.clear(); } this.updatePowerUi(); this.updateComboUi(); this.render(); requestAnimationFrame(t => this.frame(t)); }
